import unittest
from solution import retry

class ContractTests(unittest.TestCase):
    def test_00(self):
        calls=[]
        def f():
            calls.append(1)
            if len(calls)<3: raise TimeoutError()
            return 9
        self.assertEqual(retry(f,3),9); self.assertEqual(len(calls),3)
    def test_01(self):
        with self.assertRaises(ValueError): retry(lambda: 1,0)
    def test_02(self):
        calls=[]
        def f():
            calls.append(1); raise RuntimeError('fatal')
        with self.assertRaises(RuntimeError): retry(f,4)
        self.assertEqual(len(calls),1)
    def test_03(self):
        with self.assertRaises(TimeoutError): retry(lambda: (_ for _ in ()).throw(TimeoutError()),2)

